window.renderAnnualPlayerRanking=block=>`<div class="awards-table-wrap"><table class="awards-table annual-ranking-table"><caption class="sr-only">Top 20 jogadores de ${block.year}</caption><thead><tr><th>Posição</th><th>Jogador</th><th>País</th><th>Tag</th></tr></thead><tbody>${block.entries.map(entry=>{const key=s=>normalizeText(s).replace(/0/g,'o').replace(/[^a-z0-9]/g,'');const p=players.find(p=>key(p.name)===key(entry.name));return `<tr><td><b>#${entry.rank}</b></td><td>${p?`<button class="award-source" data-player="${players.indexOf(p)}">${escapeHtml(window.HBSTV?.name(entry.name)||entry.name)} ↗</button>`:`<strong>${escapeHtml(window.HBSTV?.name(entry.name)||entry.name)}</strong>`}</td><td>Brasil</td><td>${escapeHtml(entry.team)}</td></tr>`;}).join('')}</tbody></table></div><p class="source-note">${escapeHtml(block.source)}</p>`;
